import { useState, type FormEvent } from 'react';
import type { Range } from './Component';

export function useRangePair(
  min: number,
  max: number,
  onApply: (range: Range) => void,
) {
  const [start, setStart] = useState('');
  const [end, setEnd] = useState('');
  const [error, setError] = useState({
    message: '',
    startInvalid: false,
    endInvalid: false,
  });
  const options = Array.from({ length: max - min + 1 }, (_, index) => min + index);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (start === '' || end === '') {
      setError({
        message: 'Choose both values',
        startInvalid: start === '',
        endInvalid: end === '',
      });
      return;
    }

    const range = { start: Number(start), end: Number(end) };
    if (range.start > range.end) {
      setError({
        message: 'Range order',
        startInvalid: false,
        endInvalid: true,
      });
      return;
    }

    setError({ message: '', startInvalid: false, endInvalid: false });
    onApply(range);
  }

  return { start, end, setStart, setEnd, error, options, submit };
}
