import { useState } from 'react';
import type { Folder } from './Component';

type ResolvedPath = { names: string[]; children: Folder[] };

export type FolderBrowserModel = {
  currentPath: string;
  children: Folder[];
  canGoBack: boolean;
  enter: (id: string) => void;
  back: () => void;
};

function resolvePath(folders: Folder[], path: string[]): ResolvedPath {
  let children: Folder[] = folders;
  const names: string[] = [];

  for (const id of path) {
    const folder: Folder | undefined = children.find(
      (candidate: Folder): boolean => candidate.id === id,
    );
    if (!folder) break;
    names.push(folder.name);
    children = folder.children;
  }

  return { names, children };
}

export function useFolderBrowser(
  folders: Folder[],
  onNavigate: (path: string[]) => void,
): FolderBrowserModel {
  const [path, setPath] = useState<string[]>([]);
  const resolved: ResolvedPath = resolvePath(folders, path);
  const currentPath: string = '/' + resolved.names.join('/');
  const canGoBack: boolean = path.length > 0;

  function enter(id: string): void {
    const nextPath: string[] = [...path, id];
    setPath(nextPath);
    onNavigate([...nextPath]);
  }

  function back(): void {
    if (path.length === 0) return;
    const nextPath: string[] = path.slice(0, -1);
    setPath(nextPath);
    onNavigate([...nextPath]);
  }

  return { currentPath, children: resolved.children, canGoBack, enter, back };
}
