export type Props = {
  initialTags: string[];
  onChange: (tags: string[]) => void;
};

export function Component({ initialTags, onChange }: Props) {
  const [tags, setTags] = useState(() => [...initialTags]);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  return (
    <form
      aria-label="Tag editor"
      data-testid="panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#f2f6fc',
        color: '#1d3150',
        padding: 16,
        gap: 8,
      }}
      onSubmit={(event) => {
        event.preventDefault();
        const tag = input.trim();

        if (tag === '') {
          setError('Empty tag');
          return;
        }
        if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
          setError('Duplicate tag');
          return;
        }

        const nextTags = [...tags, tag];
        setTags(nextTags);
        setInput('');
        setError('');
        onChange([...nextTags]);
      }}
    >
      <label>
        Add tag
        <input
          type="text"
          value={input}
          onChange={(event) => setInput(event.currentTarget.value)}
        />
      </label>
      <button type="submit">Add</button>
      {error && <p role="alert">{error}</p>}
      <ul aria-label="Tags">
        {tags.map((tag) => (
          <li key={tag}>
            <span>{tag}</span>
            <button
              type="button"
              onClick={() => {
                const nextTags = tags.filter((existing) => existing !== tag);
                setTags(nextTags);
                setError('');
                onChange([...nextTags]);
              }}
            >
              {'Remove ' + tag}
            </button>
          </li>
        ))}
      </ul>
    </form>
  );
}
